import{_ as t,o as e,c as o,a2 as c}from"./chunks/framework.DbKnw1Aw.js";const p=JSON.parse('{"title":"规则分类","description":"","frontmatter":{},"headers":[],"relativePath":"guide/rules.md","filePath":"guide/rules.md","lastUpdated":1794385075000}'),a={name:"guide/rules.md"};function r(i,d,l,n,s,u){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="规则分类" tabindex="-1">规则分类 <a class="header-anchor" href="#规则分类" aria-label="Permalink to &quot;规则分类&quot;">​</a></h1><p>客户端按顺序从上往下匹配规则，<strong>命中第一条就停止</strong>。所以规则分类不仅决定&quot;哪些流量单独分组&quot;，它们的先后顺序也决定了优先级。</p><h2 id="_18-个分类" tabindex="-1">18 个分类 <a class="header-anchor" href="#_18-个分类" aria-label="Permalink to &quot;18 个分类&quot;">​</a></h2><p>每个分类会生成一组规则和一个同名策略组。Clash 用 <code>GEOSITE</code> / <code>GEOIP</code> 规则引用分类名，sing-box 下载对应的远程规则集。</p><table tabindex="0"><thead><tr><th>策略组</th><th>标识</th><th>域名分类（Geo-Site）</th><th>IP 分类（Geo-IP）</th><th>默认</th></tr></thead><tbody><tr><td><code>🛑 广告拦截</code></td><td><code>Ad Block</code></td><td><code>category-ads-all</code></td><td>—</td><td>拦截</td></tr><tr><td><code>💬 AI 服务</code></td><td><code>AI Services</code></td><td><code>openai</code> <code>anthropic</code> <code>jetbrains-ai</code> <code>perplexity</code></td><td>—</td><td></td></tr><tr><td><code>📺 哔哩哔哩</code></td><td><code>Bilibili</code></td><td><code>bilibili</code></td><td>—</td><td></td></tr><tr><td><code>📹 油管视频</code></td><td><code>Youtube</code></td><td><code>youtube</code></td><td>—</td><td></td></tr><tr><td><code>🔍 谷歌服务</code></td><td><code>Google</code></td><td><code>google</code></td><td><code>google</code></td><td></td></tr><tr><td><code>🏠 私有网络</code></td><td><code>Private</code></td><td>—</td><td><code>private</code></td><td>直连</td></tr><tr><td><code>🔒 国内服务</code></td><td><code>Location:CN</code></td><td><code>geolocation-cn</code></td><td><code>cn</code></td><td>直连</td></tr><tr><td><code>📲 电报消息</code></td><td><code>Telegram</code></td><td>—</td><td><code>telegram</code></td><td></td></tr><tr><td><code>🐱 Github</code></td><td><code>Github</code></td><td><code>github</code> <code>gitlab</code></td><td>—</td><td></td></tr><tr><td><code>☁️ 云服务</code></td><td><code>Cloud Services</code></td><td><code>aws</code> <code>azure</code> <code>digitalocean</code> <code>heroku</code> <code>dropbox</code></td><td>—</td><td></td></tr><tr><td><code>Ⓜ️ 微软服务</code></td><td><code>Microsoft</code></td><td><code>microsoft</code></td><td>—</td><td>直连</td></tr><tr><td><code>🍏 苹果服务</code></td><td><code>Apple</code></td><td><code>apple</code></td><td>—</td><td>直连</td></tr><tr><td><code>🌐 社交媒体</code></td><td><code>Social Media</code></td><td><code>facebook</code> <code>instagram</code> <code>twitter</code> <code>tiktok</code> <code>linkedin</code></td><td>—</td><td></td></tr><tr><td><code>🎬 流媒体</code></td><td><code>Streaming</code></td><td><code>netflix</code> <code>hulu</code> <code>disney</code> <code>hbo</code> <code>amazon</code> <code>bahamut</code></td><td>—</td><td></td></tr><tr><td><code>🎮 游戏平台</code></td><td><code>Gaming</code></td><td><code>steam</code> <code>epicgames</code> <code>ea</code> <code>ubisoft</code> <code>blizzard</code></td><td>—</td><td></td></tr><tr><td><code>📚 教育资源</code></td><td><code>Education</code></td><td><code>coursera</code> <code>edx</code> <code>udemy</code> <code>khanacademy</code> <code>category-scholar-!cn</code></td><td>—</td><td></td></tr><tr><td><code>💰 金融服务</code></td><td><code>Financial</code></td><td><code>paypal</code> <code>visa</code> <code>mastercard</code> <code>stripe</code> <code>wise</code></td><td>—</td><td></td></tr><tr><td><code>🌐 非中国</code></td><td><code>Non-China</code></td><td><code>geolocation-!cn</code></td><td>—</td><td></td></tr></tbody></table><ul><li>表格按默认顺序排列。&quot;标识&quot;是订阅链接参数 <code>selectedRules</code> 中使用的名称。</li><li><strong>默认</strong>一列是该策略组导入客户端后默认选中的出站：直连即 <code>DIRECT</code>，拦截即 <code>REJECT</code>；空白表示默认跟随 <code>🚀 节点选择</code>（走代理）。默认项只是首选，组内其他选项仍可在客户端里手动切换，见<a href="./groups">策略组</a>。</li><li>所有未命中的流量最后进入 <code>🐟 漏网之鱼</code>。</li></ul><h2 id="预设" tabindex="-1">预设 <a class="header-anchor" href="#预设" aria-label="Permalink to &quot;预设&quot;">​</a></h2><table tabindex="0"><thead><tr><th>预设</th><th>包含的分类</th></tr></thead><tbody><tr><td>精简</td><td>私有网络、国内服务、非中国</td></tr><tr><td>均衡</td><td>精简 + AI 服务、油管视频、谷歌服务、电报消息</td></tr><tr><td>全面</td><td>全部 18 个分类</td></tr></tbody></table><p>预设按表格中的固定顺序生成。在预设下点选卡片、拖动或使用推荐排序，会切换到&quot;自定义&quot;，并以当前预设为起点。显式点击&quot;自定义&quot;则恢复你上一次的自定义勾选与顺序。</p><h2 id="排序原则" tabindex="-1">排序原则 <a class="header-anchor" href="#排序原则" aria-label="Permalink to &quot;排序原则&quot;">​</a></h2><p>如果一个大分类排在它包含的小分类前面，小分类的流量会被大分类先截走，小分类的策略组就形同虚设。例如 <code>油管视频</code> 的域名几乎都在 <code>谷歌服务</code> 里，<code>谷歌服务</code> 一旦排在前面，YouTube 的流量就进不了 <code>📹 油管视频</code>。</p><p>所以：<strong>越具体的分类越靠前，国内服务、非中国这类大合集放在最后。</strong></p><ul><li>拖动卡片左侧的手柄调整顺序，卡片左上角的序号就是当前优先级。</li><li>卡片右上角显示该分类的域名数量，可以直观判断大小。</li></ul><h3 id="推荐排序" tabindex="-1">推荐排序 <a class="header-anchor" href="#推荐排序" aria-label="Permalink to &quot;推荐排序&quot;">​</a></h3><p>点击&quot;推荐排序&quot;，按以下规则重排：</p><ol><li>广告拦截放在最前，它横跨国内外，需要最先匹配；</li><li>私有网络、电报消息这类只有 IP 规则的分类紧随其后，它们与域名分类互不冲突；</li><li>其余分类按包含关系排序，被包含的排在前面；同一层按域名数从小到大，因此大合集自然落到最后。</li></ol><p>推荐排序只调整顺序，不改变勾选。它与下面的冲突检测使用同一套判断，结果不会产生冲突。</p><h2 id="在线分析与冲突提示" tabindex="-1">在线分析与冲突提示 <a class="header-anchor" href="#在线分析与冲突提示" aria-label="Permalink to &quot;在线分析与冲突提示&quot;">​</a></h2><p>打开页面后，前端通过 <code>/api/geosite/:name</code> 获取每个分类的域名名单，在浏览器中计算每个分类的域名数，以及两两之间的覆盖比例。名单来自 <a href="https://github.com/MetaCubeX/meta-rules-dat" target="_blank" rel="noreferrer">MetaCubeX/meta-rules-dat</a>，与 Clash（mihomo）使用的 <code>geosite.dat</code> 同源。</p><p>当已选分类 A 排在 B 后面，且同时满足以下条件时，会提示&quot;A 有 N%（M 个）的域名会先被 B 截走&quot;，并提供&quot;移到 B 前面&quot;的按钮：</p><ul><li>A 被 B 覆盖的比例<strong>高于</strong> B 被 A 覆盖的比例，也就是 B 才是包含的一方。云服务与微软这类只是共享一部分域名（Azure）的情况不会提示；</li><li>覆盖比例达到 <strong>20%</strong>，或者被截走的域名达到 <strong>150 个</strong>。后一个条件用于广告拦截这类横跨国内外、比例不高但数量很大的分类。</li></ul><p>只有 IP 规则的分类（私有网络、电报消息）没有域名数据，不参与分析。</p>',22)])])}const b=t(a,[["render",r]]);export{p as __pageData,b as default};
